<script setup>
import {computed,onMounted,ref} from 'vue';
import {ElAlert,ElButton,ElCheckbox,ElEmpty,ElForm,ElFormItem,ElInput,ElOption,ElPagination,ElSelect,ElSkeleton,ElSwitch,ElTag,ElMessage,ElMessageBox} from 'element-plus';
const props=defineProps({mode:String,eventId:Number,language:{type:String,default:'zh'}});
const t=(zh,en)=>props.language==='en'?en:zh;
const data=ref(null),orders=ref({items:[],total:0}),busy=ref(false),loading=ref(true),error=ref(''),page=ref(1),filter=ref('');
const company=ref({}),fees=ref({}),checkout=ref(null),conditions=ref(''),accepted=ref(false);
const transfer=ref({payer:'',reference:''}),refund=ref({reason:''}),invoice=ref({kind:'company',title:'',tax_id:'',email:''});
const finance=ref({amount:'',reference:'',note:'',number:''});
const detail=computed(()=>props.mode==='payment-detail'),settings=computed(()=>props.mode==='company-payments');
const id=Number(location.pathname.match(/^\/payments\/(\d+)\//)?.[1]);
const order=computed(()=>data.value?.order),paid=computed(()=>order.value?.status==='paid');
const refundable=computed(()=>['paid','payment_exception'].includes(order.value?.status));
const amount=value=>new Intl.NumberFormat(props.language==='en'?'en-CN':'zh-CN',{style:'currency',currency:'CNY'}).format(Number(value));
const statuses={awaiting:['待付款','Awaiting payment'],review:['待核对','Awaiting verification'],paid:['已到账','Paid'],payment_exception:['到账待核对','Receipt needs review'],refund_requested:['退款待处理','Refund requested'],refunded:['已全额退款','Fully refunded'],requested:['待开票','Invoice requested'],issued:['已开票','Invoice issued']};
const label=state=>statuses[state]?t(...statuses[state]):state;
const auditLabels={order_created:['生成订单','Order created'],payment_conditions_accepted:['同意缴费说明','Payment conditions accepted'],transfer_claimed:['提交汇款信息','Transfer submitted'],checkout_created:['发起在线支付','Online checkout started'],payment_confirmed:['确认到账','Receipt confirmed'],invoice_requested:['申请开票','Invoice requested'],invoice_issued:['登记已开票','Invoice recorded'],refund_requested:['申请退款','Refund requested'],refund_rejected:['拒绝退款申请','Refund declined'],refund_confirmed:['登记已退款','Refund recorded']};
const auditLabel=action=>action==='payment_exception'?t('到账待核对','Receipt needs review'):action==='checkout_closed'?t('关闭旧支付单','Previous checkout closed'):auditLabels[action]?t(...auditLabels[action]):t('财务记录更新','Financial record updated');
const date=value=>new Intl.DateTimeFormat(props.language==='en'?'en-GB':'zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
async function api(url,method,payload){
 const session=method?await window.MeetPortal.refreshSession():null;
 if(method&&!session?.user)throw new Error(t('登录已失效，请重新登录。','Your session expired. Log in again.'));
 const response=await fetch(url,{method:method||'GET',credentials:'same-origin',cache:'no-store',headers:method?{'Content-Type':'application/json','X-CSRF-Token':session.csrf_token}:{},...(method?{body:JSON.stringify(payload)}:{})});
 if(!response.ok){let result;try{result=await response.json();}catch{}throw new Error(result?.message||result?.error?.message||(response.status===403?t('没有操作权限，或会议已锁定/撤回。','Permission denied, or the conference is locked or withdrawn.'):response.status===409?t('订单或配置状态已变化，请刷新并核对。','Order or settings changed. Refresh and verify.'):t('操作未完成，请检查信息后重试。','Operation failed. Check the details and retry.')));}
 return response.json();
}
async function loadOrders(){orders.value=await api(`/api/conferences/${props.eventId}/orders?page=${page.value}${filter.value?'&state='+filter.value:''}`);}
async function load(){
 loading.value=true;error.value='';
 try{
  if(settings.value){data.value=await api('/api/company/payments/');company.value={...data.value.company};delete company.value.audit;}
  else if(detail.value){data.value=await api(`/api/payments/${id}/`);checkout.value=data.value.checkout||null;accepted.value=Boolean(data.value.order?.terms_accepted_at);finance.value.amount=data.value.order?.amount||data.value.amount;}
  else{data.value=await api(`/api/conferences/${props.eventId}/fees`);fees.value=Object.fromEntries(data.value.forms.map(f=>[f.id,f.base_price]));conditions.value=data.value.conditions||'';await loadOrders();}
 }catch(e){error.value=e.message;}finally{loading.value=false;}
}
async function run(task){if(busy.value)return;busy.value=true;error.value='';try{await task();ElMessage.success(t('已保存','Saved'));}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function saveCompany(){await run(async()=>{await api('/api/company/payments/','PUT',company.value);await load();});}
async function saveFee(form){await run(async()=>{await api(`/api/conferences/${props.eventId}/fees`,'PUT',{form_id:form.id,base_price:fees.value[form.id],conditions:conditions.value});await load();});}
async function action(name,payload,confirmation){
 if(confirmation){try{await ElMessageBox.confirm(confirmation,t('确认财务操作','Confirm financial action'),{confirmButtonText:t('确认记录','Record'),cancelButtonText:t('取消','Cancel'),type:'warning'});}catch{return;}}
 await run(async()=>{await api(`/api/payments/${id}/${name}`,'POST',payload);await load();});
}
async function start(provider){await run(async()=>{await api(`/api/payments/${id}/checkout`,'POST',{provider,accepted_terms:accepted.value});await load();});}
async function changePage(){await run(loadOrders);}
onMounted(load);
</script>

<template>
 <section class="payment-workspace" data-test="payment-workspace" :aria-busy="loading||busy">
  <div class="payment-toolbar"><p>{{t('收款主体：遇见科技','Collection by Meet Technology')}}</p><div><ElButton v-if="!settings&&!detail" tag="a" :href="`/conference/${eventId}/operations/`">{{t('办会管理','Conference operations')}}</ElButton><ElButton v-if="detail" tag="a" :href="data?.is_owner?'/participation/':`/conference/${eventId}/payments/`">{{t('返回列表','Back to list')}}</ElButton><ElButton :loading="loading" @click="load">{{t('刷新状态','Refresh status')}}</ElButton></div></div>
  <ElAlert v-if="error" data-test="payment-error" type="error" :title="error" :closable="false" show-icon/>
  <ElSkeleton v-if="loading" :rows="8" animated/>
  <template v-else-if="data">
   <template v-if="settings">
    <section class="surface payment-section"><h2>{{t('公司对公收款账户','Company bank account')}}</h2><p class="payment-note">{{t('仅平台管理员可维护。会议管理者无法更改收款账户，启用前请核对公司开户资料。','Only platform administrators can change this account. Verify the company bank details before enabling collection.')}}</p>
     <ElForm label-position="top" @submit.prevent="saveCompany" class="payment-form">
      <ElFormItem :label="t('启用公司收款','Enable company collection')"><ElSwitch v-model="company.enabled" :aria-label="t('启用公司收款','Enable company collection')"/></ElFormItem>
      <ElFormItem :label="t('开户名称（公司全称）','Account holder (legal company name)')"><ElInput v-model="company.account_name" name="account_name" maxlength="200" required/></ElFormItem>
      <ElFormItem :label="t('开户银行及支行','Bank and branch')"><ElInput v-model="company.bank_name" name="bank_name" maxlength="200" required/></ElFormItem>
      <ElFormItem :label="t('对公银行账号','Company bank account number')"><ElInput v-model="company.account_number" name="account_number" maxlength="40" inputmode="numeric" required/></ElFormItem>
      <ElFormItem :label="t('财务联系方式','Finance contact')"><ElInput v-model="company.contact" name="contact" maxlength="200" required/></ElFormItem>
      <ElButton type="primary" native-type="submit" :loading="busy">{{t('保存公司收款配置','Save company collection settings')}}</ElButton>
     </ElForm>
    </section>
    <section class="surface payment-section"><h2>{{t('在线支付通道','Online payment channels')}}</h2><div class="payment-channels"><span>{{t('微信扫码','WeChat QR')}} <ElTag :type="data.gateways.wechat?'success':'info'">{{data.gateways.wechat?t('已就绪','Ready'):t('未启用','Disabled')}}</ElTag></span><span>{{t('支付宝','Alipay')}} <ElTag :type="data.gateways.alipay?'success':'info'">{{data.gateways.alipay?t('已就绪','Ready'):t('未启用','Disabled')}}</ElTag></span></div><p class="payment-note">{{t('在线支付需配置公司商户资料与公网 HTTPS 回调。商户密钥由系统运维在服务器配置，不在网页中显示。','Online payments require company merchant settings and a public HTTPS callback. Merchant keys are configured on the server and never displayed here.')}}</p></section>
   </template>
   <template v-else-if="!detail">
    <ElAlert v-if="!data.company_ready" type="warning" :closable="false" show-icon :title="t('公司收款账户尚未启用，请联系平台管理员配置后再开放收费报名。','Company collection is not configured. Contact the platform administrator before opening paid registration.')"/>
    <section class="surface payment-section"><h2>{{data.event.title}}</h2><p class="payment-note">{{t('报名金额由后台计算。已有报名保留原金额；学生票、普通票和早鸟票可分别创建报名表，早鸟表设置截止时间。','Amounts are calculated on the server. Existing registrations keep their prices. Use separate forms for student, standard and early-bird tickets; set an early-bird closing date.')}}</p><ElEmpty v-if="!data.forms.length" :description="t('尚无报名表，请先在办会管理创建。','Create a registration form in conference operations first.')"/>
     <ElForm label-position="top" class="payment-form"><ElFormItem :label="t('本会议缴费与退款说明（保存费用时一并保存）','Payment and refund conditions (saved with fees)')"><ElInput v-model="conditions" name="payment_conditions" type="textarea" :rows="4" maxlength="4000" show-word-limit/></ElFormItem></ElForm><form v-for="form in data.forms" :key="form.id" class="payment-fee" @submit.prevent="saveFee(form)"><div><strong>{{form.title}}</strong><a :href="form.url">{{t('配置字段与开放时间','Configure fields and dates')}}</a></div><label :for="`fee-${form.id}`">{{t('基础费用（人民币）','Base fee (CNY)')}}</label><ElInput :id="`fee-${form.id}`" v-model="fees[form.id]" inputmode="decimal" :aria-label="t('基础费用','Base fee')"/><ElButton native-type="submit" type="primary" :loading="busy" :disabled="data.event.locked">{{t('保存费用','Save fee')}}</ElButton></form>
     <p class="payment-note">{{t('保存收费配置后，参会者不能自行修改报名以变更金额；信息更正请联系主办方。其他收费选项可在原生表单中配置。','After fee setup, participants must contact the organizer for registration corrections. Additional paid options can be configured in the native form.')}}</p>
    </section>
    <section class="surface payment-section"><div class="payment-list-title"><h2>{{t('订单与财务记录','Orders & finance')}}</h2><ElButton tag="a" :href="`/api/conferences/${eventId}/orders.csv${filter?'?state='+filter:''}`">{{t('导出 CSV','Export CSV')}}</ElButton></div><div class="payment-list-filter"><ElSelect v-model="filter" :aria-label="t('订单状态','Order status')" @change="page=1;changePage()"><ElOption :label="t('全部状态','All statuses')" value=""/><ElOption v-for="status in ['awaiting','review','paid','payment_exception','refund_requested','refunded']" :key="status" :label="label(status)" :value="status"/></ElSelect><span>{{orders.total}} {{t('笔订单','orders')}}</span></div><p v-if="!data.can_confirm" class="payment-note">{{t('您可以查看和导出本会议订单，到账、退款及开票由公司财务管理员确认。','You can view and export this conference’s orders. Company finance confirms receipts, refunds and invoices.')}}</p>
     <ElEmpty v-if="!orders.items.length" :description="t('暂无订单。收费报名审核通过后生成订单。','No orders yet. Orders are created after paid registrations are approved.')"/>
     <article v-for="item in orders.items" :key="item.registration_id" class="payment-order-row"><div><strong>{{item.name}}</strong><ElTag :type="item.order.status==='paid'?'success':'info'">{{label(item.order.status)}}</ElTag><p>{{item.form_title}} · {{item.order.number}}</p><small>{{item.email}}</small><p v-if="item.order.invoice">{{t('发票','Invoice')}}: {{label(item.order.invoice.status)}}</p></div><div><strong class="payment-row-amount">{{amount(item.order.amount)}}</strong><ElButton tag="a" :href="item.url" type="primary" plain>{{data.can_confirm?t('处理订单','Process order'):t('查看详情','View details')}}</ElButton></div></article>
     <ElPagination v-if="orders.total>25" v-model:current-page="page" :page-size="25" :total="orders.total" layout="prev,pager,next" @current-change="changePage"/>
    </section>
   </template>
   <template v-else>
    <section class="surface payment-section payment-summary"><div><ElTag v-if="order" :type="paid?'success':'warning'">{{label(order.status)}}</ElTag><h2>{{data.event_title}}</h2><p>{{data.form_title}}</p><p v-if="data.name">{{data.name}} · {{data.email}}</p><small v-if="order">{{t('订单号','Order')}} {{order.number}}</small></div><div class="payment-total"><span>{{t('订单金额','Order amount')}}</span><strong>{{amount(order?.amount||data.amount)}}</strong></div></section>
    <ElAlert v-if="!data.company&&(!order||['awaiting','review'].includes(order.status))" type="warning" :closable="false" show-icon :title="t('公司暂未启用收款，请联系主办方。请勿向个人账户付款。','Company collection is unavailable. Contact the organizer; do not pay a personal account.')"/>
    <ElAlert v-if="!order" type="info" :closable="false" :title="t('报名审核通过后才可生成付款订单。','A payment order is available after your registration is approved.')"/>
    <section v-if="!order&&data.registration_state==='unpaid'&&data.is_owner" class="surface payment-section"><ElButton type="primary" :loading="busy" @click="action('create',{})">{{t('生成付款订单','Create payment order')}}</ElButton></section>
    <template v-if="order">
     <ElAlert v-if="order.status==='payment_exception'" type="warning" :closable="false" show-icon :title="t('已收到支付渠道到账通知，但报名状态或金额已变化。款项已记录，请联系公司财务核对，切勿重复付款。可申请全额退款。','The provider confirmed payment, but registration details changed. The receipt is recorded. Contact finance and do not pay again. You may request a full refund.')"/>
     <section v-if="data.can_pay&&data.is_owner" class="surface payment-section"><h2>{{t('选择付款方式','Choose payment method')}}</h2><div class="payment-terms"><h3>{{t('缴费与退款说明','Payment and refund conditions')}}</h3><p>{{order.conditions}}</p><ElCheckbox v-model="accepted" name="accepted_terms">{{t('我已阅读并同意以上缴费与退款说明','I have read and accept the payment and refund conditions')}}</ElCheckbox></div>
      <div v-if="data.gateways.wechat||data.gateways.alipay" class="payment-actions"><ElButton v-if="data.gateways.wechat" :loading="busy" :disabled="!accepted" @click="start('wechat')">{{t('微信扫码支付','Pay with WeChat')}}</ElButton><ElButton v-if="data.gateways.alipay" :loading="busy" :disabled="!accepted" @click="start('alipay')">{{t('支付宝支付','Pay with Alipay')}}</ElButton></div>
      <div v-if="checkout" class="payment-checkout"><img v-if="checkout.qr&&!checkout.expired" :src="checkout.qr" :alt="t('微信支付二维码','WeChat payment QR code')" width="220" height="220"><ElButton v-if="checkout.url&&!checkout.expired" tag="a" :href="checkout.url" type="primary">{{t('前往支付宝收银台','Open Alipay checkout')}}</ElButton><p>{{t('付款后点击“刷新状态”。支付信息过期时，点击上方原支付方式重新获取；系统将先核对旧交易。','Refresh after paying. If checkout expires, select the same payment method again. The previous transaction is verified first.')}}</p></div>
      <template v-else><h3>{{t('对公银行转账','Company bank transfer')}}</h3><dl class="payment-bank"><dt>{{t('开户名称','Account holder')}}</dt><dd>{{data.company.account_name}}</dd><dt>{{t('开户银行','Bank')}}</dt><dd>{{data.company.bank_name}}</dd><dt>{{t('银行账号','Account number')}}</dt><dd class="payment-bank-number">{{data.company.account_number}}</dd><dt>{{t('转账备注','Transfer note')}}</dt><dd>{{order.number}}</dd><dt>{{t('财务联系','Finance contact')}}</dt><dd>{{data.company.contact}}</dd></dl><p class="payment-note">{{t('请汇入以上公司账户，并备注订单号。提交汇款信息不代表已到账，需财务核对。','Transfer to the company account above and include the order number. Submitting transfer details does not confirm receipt; finance must verify it.')}}</p>
       <ElForm class="payment-form" label-position="top" @submit.prevent="action('transfer',{...transfer,accepted_terms:accepted})"><ElFormItem :label="t('付款人或付款单位','Payer or paying organization')"><ElInput v-model="transfer.payer" name="payer" required maxlength="120"/></ElFormItem><ElFormItem :label="t('银行汇款流水或回单号','Bank transfer reference')"><ElInput v-model="transfer.reference" name="transfer_reference" required maxlength="120"/></ElFormItem><ElButton type="primary" native-type="submit" :loading="busy" :disabled="!accepted">{{t('提交汇款信息，等待核对','Submit transfer for verification')}}</ElButton></ElForm>
      </template>
     </section>
     <section v-if="order.transfer" class="surface payment-section"><h2>{{t('已提交的汇款信息','Submitted transfer details')}}</h2><p>{{order.transfer.payer}} · {{order.transfer.reference}}</p><p class="payment-note">{{t('这条信息由参会者填写，到账状态以财务核对为准。','These details were entered by the participant. Receipt depends on finance verification.')}}</p></section>
     <section v-if="order.payment" class="surface payment-section"><h2>{{t('到账记录','Payment receipt')}}</h2><p>{{t('流水','Reference')}}: {{order.payment.reference}}</p><p>{{date(order.payment.at)}}</p><ElButton tag="a" :href="`/payments/${id}/receipt/`" target="_blank" rel="noopener">{{t('查看 / 打印付款确认单','View / print payment confirmation')}}</ElButton></section>
     <section v-if="data.can_confirm&&!data.payment_channel&&['awaiting','review'].includes(order.status)" class="surface payment-section"><h2>{{t('公司财务：确认到账','Company finance: verify receipt')}}</h2><p class="payment-note">{{t('仅在银行核对实际到账后登记。在线支付订单由验签回调确认，不能手动标记。','Record only after verifying the bank receipt. Online payments are confirmed by signed provider notifications.') }}</p><ElForm label-position="top" class="payment-form" @submit.prevent="action('confirm',finance,t('确认已在公司银行账户核对这笔足额到账？','Have you verified this full receipt in the company bank account?'))"><ElFormItem :label="t('实际到账金额','Amount received')"><ElInput v-model="finance.amount" name="received_amount" inputmode="decimal" required/></ElFormItem><ElFormItem :label="t('银行到账流水号','Bank receipt reference')"><ElInput v-model="finance.reference" name="bank_reference" required maxlength="120"/></ElFormItem><ElButton type="primary" native-type="submit" :loading="busy">{{t('确认已到账','Confirm receipt')}}</ElButton></ElForm></section>
     <section v-if="paid&&data.is_owner" class="surface payment-section"><h2>{{t('申请开票','Request an invoice')}}</h2><ElForm v-if="order.invoice?.status!=='issued'" label-position="top" class="payment-form" @submit.prevent="action('invoice',invoice)"><ElFormItem :label="t('抬头类型','Invoice type')"><ElSelect v-model="invoice.kind"><ElOption :label="t('企业','Company')" value="company"/><ElOption :label="t('个人','Individual')" value="personal"/></ElSelect></ElFormItem><ElFormItem :label="t('发票抬头','Invoice title')"><ElInput v-model="invoice.title" name="invoice_title" required maxlength="200"/></ElFormItem><ElFormItem v-if="invoice.kind==='company'" :label="t('纳税人识别号','Taxpayer ID')"><ElInput v-model="invoice.tax_id" name="tax_id" required maxlength="20"/></ElFormItem><ElFormItem :label="t('接收发票的邮箱','Invoice email')"><ElInput v-model="invoice.email" name="invoice_email" type="email" required maxlength="254"/></ElFormItem><ElButton native-type="submit" :loading="busy">{{t('提交开票申请','Submit invoice request')}}</ElButton></ElForm><p class="payment-note">{{t('税务发票由公司财务实际开具后发送，付款确认单不能替代发票。','Company finance issues and sends tax invoices. A payment confirmation is not a tax invoice.')}}</p></section>
     <section v-if="order.invoice" class="surface payment-section"><h2>{{t('开票申请记录','Invoice request')}}</h2><ElTag>{{label(order.invoice.status)}}</ElTag><p>{{order.invoice.title}} · {{order.invoice.email}}</p><p v-if="order.invoice.tax_id">{{t('纳税人识别号','Taxpayer ID')}}: {{order.invoice.tax_id}}</p><p v-if="order.invoice.number">{{t('发票号','Invoice number')}}: {{order.invoice.number}}</p><ElForm v-if="data.can_confirm&&paid&&order.invoice.status==='requested'" label-position="top" class="payment-form" @submit.prevent="action('invoice-issued',{number:finance.number},t('确认已实际开具并发送此发票？','Have you issued and sent this invoice?'))"><ElFormItem :label="t('实际开具的发票号','Issued invoice number')"><ElInput v-model="finance.number" name="issued_invoice_number" required maxlength="100"/></ElFormItem><ElButton native-type="submit" :loading="busy">{{t('登记已开票','Record issued invoice')}}</ElButton></ElForm></section>
     <section v-if="refundable&&data.is_owner" class="surface payment-section"><h2>{{t('申请全额退款','Request a full refund')}}</h2><p class="payment-note">{{t('退款须经公司财务审核并实际退回，完成后报名将撤销。当前不支持部分退款。','Finance reviews and processes refunds. A completed full refund withdraws your registration. Partial refunds are not supported.') }}</p><ElForm label-position="top" class="payment-form" @submit.prevent="action('refund',refund)"><ElFormItem :label="t('退款原因','Reason for refund')"><ElInput v-model="refund.reason" name="refund_reason" type="textarea" maxlength="500" required/></ElFormItem><ElButton native-type="submit" :loading="busy">{{t('提交退款申请','Request refund')}}</ElButton></ElForm></section>
     <section v-if="order.refund" class="surface payment-section"><h2>{{t('退款记录','Refund record')}}</h2><p>{{order.refund.reason}}</p><p v-if="order.refund.note">{{order.refund.note}}</p><p v-if="order.refund.reference">{{t('退款流水','Refund reference')}}: {{order.refund.reference}}</p><ElForm v-if="data.can_confirm&&order.status==='refund_requested'" label-position="top" class="payment-form" @submit.prevent="action('refund-decision',{...finance,action:'confirm'},t('确认已实际全额退款，并已处理原发票？此操作会撤销报名。','Have you completed the full refund and handled the original invoice? This withdraws the registration.'))"><ElFormItem :label="t('退款金额','Refund amount')"><ElInput v-model="finance.amount" name="refund_amount" inputmode="decimal" required/></ElFormItem><ElFormItem :label="t('实际退款流水','Completed refund reference')"><ElInput v-model="finance.reference" name="refund_reference" required maxlength="120"/></ElFormItem><ElFormItem :label="t('处理说明（含发票处理情况）','Processing note (including invoice handling)')"><ElInput v-model="finance.note" name="refund_note" type="textarea" required maxlength="500"/></ElFormItem><div class="payment-actions"><ElButton type="primary" native-type="submit" :loading="busy">{{t('登记已全额退款','Record completed full refund')}}</ElButton><ElButton :loading="busy" @click="action('refund-decision',{action:'reject',note:finance.note})">{{t('拒绝申请并保存说明','Reject with note')}}</ElButton></div></ElForm></section>
     <section v-if="order.audit" class="surface payment-section"><h2>{{t('操作记录','Audit history')}}</h2><ol class="payment-audit"><li v-for="(entry,index) in order.audit" :key="index"><time>{{date(entry.at)}}</time><span>{{auditLabel(entry.action)}}</span><small v-if="entry.by">{{t('操作账号','User')}} #{{entry.by}}</small></li></ol></section>
    </template>
   </template>
  </template>
 </section>
